{"renderable":true,"reason":"The photos show a two-and-a-half storey clapboard house with a front gable, a full-width open porch band across the ground floor of the front, a small gabled wing on the left, roof dormers on the right slope and a brick chimney. The owner's new note shrinks the left wing further and removes the porch glazing/screens, leaving the porch framing open; both changes are applied while everything else is kept.","confidence":0.82,"subject":"A two-and-a-half storey white clapboard house with a front gable, an open full-width ground-floor porch, a small gabled wing on the left and two roof dormers to the right.","subjectKind":"building","name":"3D twin - House","description":"Massing model of a wood-frame clapboard house: a tall front-gabled main block (two storeys plus attic gable) with a steep main roof and two dormers on the right slope, an open ground-floor porch spanning the front held on posts with rails and a short flight of steps, a small two-storey gabled wing on the left, and a brick chimney at the wing junction. The porch band is left open (no glazing, no screens); the left wing is reduced to a narrow, shallow projection.","parts":[{"name":"mainBlock","kind":"wall","description":"two-storey clapboard main block"},{"name":"gableWall","kind":"wall","description":"front gable attic wall"},{"name":"roofMain","kind":"roof","description":"main gable roof slopes"},{"name":"dormerWall","kind":"wall","description":"roof dormer bodies"},{"name":"dormerRoof","kind":"roof","description":"roof dormer roofs"},{"name":"porchWall","kind":"wall","description":"open porch framing: posts, rails and beam"},{"name":"porchDoor","kind":"wood","description":"porch entry door with glazed upper"},{"name":"porchRoof","kind":"roof","description":"dark porch roof"},{"name":"porchBase","kind":"stone","description":"porch foundation and entrance steps"},{"name":"sideWing","kind":"wall","description":"small left two-storey gabled wing, reduced projection"},{"name":"wingRoof","kind":"roof","description":"wing cross gable roof"},{"name":"windows","kind":"glass","description":"block, dormer and wing windows"},{"name":"chimney","kind":"stone","description":"brick chimney"},{"name":"pavement","kind":"pavement","description":"front sidewalk"}],"code":"const CLAD = '#eae7e0';
  const GLASS = '#8a969c';
  const ROOF = '#3c3f43';
  const STONE = '#b6b0a6';
  const BRICK = '#8f5b4a';
  const PAVE = '#c0bcb3';

  const mainBlock = api.part('mainBlock', 'wall', 'two storey clapboard block');
  const gableWall = api.part('gableWall', 'wall', 'front gable attic wall');
  const roofMain = api.part('roofMain', 'roof', 'main gable roof slopes');
  const dormerWall = api.part('dormerWall', 'wall', 'roof dormer bodies');
  const dormerRoof = api.part('dormerRoof', 'roof', 'roof dormer roofs');
  const porchWall = api.part('porchWall', 'wall', 'open porch framing posts and rails');
  const porchDoor = api.part('porchDoor', 'wood', 'porch entry door with glazed upper');
  const porchRoof = api.part('porchRoof', 'roof', 'dark porch roof');
  const porchBase = api.part('porchBase', 'stone', 'porch foundation and steps');
  const sideWing = api.part('sideWing', 'wall', 'small left two storey gabled wing');
  const wingRoof = api.part('wingRoof', 'roof', 'wing cross gable roof');
  const windows = api.part('windows', 'glass', 'block, dormer and wing windows');
  const chimney = api.part('chimney', 'stone', 'brick chimney');
  const pavement = api.part('pavement', 'pavement', 'front sidewalk');

  function slab(part, w, t, d, x, y, z, rx, rz, kind, color) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, t, d), api.material(kind, color));
    m.rotation.x = rx;
    m.rotation.z = rz;
    m.position.set(x, y, z);
    part.add(m);
    return m;
  }

  // ---- main two storey block: sides x -3.8..3.8, z -5.7..3.3 (front at z=3.3)
  mainBlock.box(7.6, 6.0, 9.0, 0, 0, -1.2, 'wall', CLAD);

  // ---- front gable attic (triangle extruded front to back)
  const tri = new THREE.Shape();
  tri.moveTo(-3.8, 6.0);
  tri.lineTo(3.8, 6.0);
  tri.lineTo(0, 8.8);
  tri.closePath();
  const triGeo = new THREE.ExtrudeGeometry(tri, { depth: 9.0, bevelEnabled: false });
  const triMesh = new THREE.Mesh(triGeo, api.material('wall', CLAD));
  triMesh.position.set(0, 0, -5.7);
  gableWall.add(triMesh);

  // ---- main gable roof slopes with eave overhang
  const ang = Math.atan2(2.8, 4.15);
  const rl = Math.sqrt(4.15 * 4.15 + 2.8 * 2.8);
  slab(roofMain, rl, 0.16, 9.8, 2.11, 7.46, -1.2, 0, -ang, 'roof', ROOF);
  slab(roofMain, rl, 0.16, 9.8, -2.11, 7.46, -1.2, 0, ang, 'roof', ROOF);

  // ---- dormers on both roof slopes
  for (const sx of [1, -1]) {
    const dx = 3.0 * sx;
    dormerWall.box(1.3, 1.3, 1.6, dx, 6.15, 0.8, 'wall', CLAD);
    slab(dormerRoof, 1.55, 0.12, 0.99, dx, 7.66, 1.25, 0.437, 0, 'roof', ROOF);
    slab(dormerRoof, 1.55, 0.12, 0.99, dx, 7.66, 0.35, -0.437, 0, 'roof', ROOF);
    windows.box(0.6, 0.6, 0.12, dx, 6.7, 1.64, 'glass', GLASS);
  }

  // ---- front porch, now open: posts, rails and beam only, no glazing, no screens
  porchWall.box(7.0, 2.6, 2.4, 0, 0.7, 4.5, 'wall', CLAD);
  for (const mx of [-3.45, -2.15, -0.85, 0.85, 2.15, 3.45]) {
    porchWall.box(0.12, 1.84, 0.2, mx, 1.3, 5.72, 'wall', CLAD);
  }
  porchWall.box(7.0, 0.16, 0.2, 0, 3.14, 5.72, 'wall', CLAD);
  porchWall.box(7.0, 0.16, 0.2, 0, 1.14, 5.72, 'wall', CLAD);

  // porch side post rows (open sides)
  porchWall.box(0.12, 1.84, 2.1, -3.5, 1.3, 4.5, 'wall', CLAD);
  porchWall.box(0.12, 1.84, 2.1, 3.5, 1.3, 4.5, 'wall', CLAD);

  // porch door with glazed upper
  porchDoor.box(1.1, 2.1, 0.1, 0, 0.7, 5.72, 'wood', '#f3f1ec');
  porchDoor.box(0.7, 0.7, 0.06, 0, 1.85, 5.81, 'glass', GLASS);

  // porch roof, shallow, sloping down to the front
  slab(porchRoof, 7.6, 0.16, 2.8, 0, 3.62, 4.6, 0.137, 0, 'roof', ROOF);

  // porch foundation and three steps
  porchBase.box(7.2, 0.7, 2.6, 0, 0, 4.5, 'stone', STONE);
  porchBase.box(1.7, 0.23, 0.36, 0, 0.47, 5.88, 'stone', STONE);
  porchBase.box(1.7, 0.23, 0.36, 0, 0.24, 6.24, 'stone', STONE);
  porchBase.box(1.7, 0.24, 0.36, 0, 0.00, 6.60, 'stone', STONE);

  // ---- left two storey wing, projection reduced again: x -5.5..-3.8, z -5.7..-0.9
  sideWing.box(1.7, 5.8, 4.8, -4.65, 0, -3.3, 'wall', CLAD);

  // wing gable end, facing left
  const t2 = new THREE.Shape();
  t2.moveTo(-2.4, 5.8);
  t2.lineTo(2.4, 5.8);
  t2.lineTo(0, 6.9);
  t2.closePath();
  const g2 = new THREE.ExtrudeGeometry(t2, { depth: 0.2, bevelEnabled: false });
  const m2 = new THREE.Mesh(g2, api.material('wall', CLAD));
  m2.rotation.y = Math.PI / 2;
  m2.position.set(-5.6, 0, -3.3);
  sideWing.add(m2);

  // wing roof, ridge running left-right
  slab(wingRoof, 1.9, 0.14, 2.75, -4.65, 6.35, -2.1, 0.429, 0, 'roof', ROOF);
  slab(wingRoof, 1.9, 0.14, 2.75, -4.65, 6.35, -4.5, -0.429, 0, 'roof', ROOF);

  // ---- brick chimney at the wing/main junction
  chimney.box(0.9, 4.2, 0.9, -3.5, 5.4, -1.3, 'stone', BRICK);

  // ---- windows: front upper pair and gable pair of the main block
  windows.box(1.0, 1.4, 0.14, 1.6, 4.1, 3.32, 'glass', GLASS);
  windows.box(1.0, 1.4, 0.14, -1.6, 4.1, 3.32, 'glass', GLASS);
  windows.box(0.8, 0.9, 0.14, 0.75, 6.7, 3.32, 'glass', GLASS);
  windows.box(0.8, 0.9, 0.14, -0.75, 6.7, 3.32, 'glass', GLASS);

  // right side wall windows
  windows.box(0.14, 1.4, 0.9, 3.82, 4.1, 0.5, 'glass', GLASS);
  windows.box(0.14, 1.4, 0.9, 3.82, 4.1, -1.5, 'glass', GLASS);
  windows.box(0.14, 1.4, 0.9, 3.82, 4.1, -3.5, 'glass', GLASS);
  windows.box(0.14, 1.2, 0.9, 3.82, 1.4, -0.5, 'glass', GLASS);
  windows.box(0.14, 1.2, 0.9, 3.82, 1.4, -2.5, 'glass', GLASS);

  // wing windows, left face and front face (resized to the smaller wing)
  windows.box(0.14, 1.3, 0.9, -5.52, 3.8, -2.1, 'glass', GLASS);
  windows.box(0.14, 1.3, 0.9, -5.52, 3.8, -4.5, 'glass', GLASS);
  windows.box(0.14, 1.3, 0.9, -5.52, 1.4, -2.1, 'glass', GLASS);
  windows.box(0.14, 1.3, 0.9, -5.52, 1.4, -4.5, 'glass', GLASS);
  windows.box(1.0, 1.3, 0.14, -4.65, 3.8, -0.82, 'glass', GLASS);
  windows.box(1.0, 1.3, 0.14, -4.65, 1.4, -0.82, 'glass', GLASS);

  // ---- sidewalk in front of the house
  pavement.box(22, 0.15, 4.0, 0, 0, 8.7, 'pavement', PAVE);","views":[{"photo":1,"x":1,"y":1.6,"z":15.5,"targetX":0,"targetY":4.2,"targetZ":3},{"photo":2,"x":8,"y":1.5,"z":13.5,"targetX":-0.5,"targetY":3.8,"targetZ":1.5},{"photo":3,"x":-10.5,"y":1.7,"z":12,"targetX":-3,"targetY":3.6,"targetZ":1}]}
